import os, base64
files = {}
files['requirements.txt'] = base64.b64decode('').decode("utf-8")
files['README.md'] = base64.b64decode('').decode("utf-8")
files['START.bat'] = base64.b64decode('').decode("utf-8")
files['STOP.bat'] = base64.b64decode('').decode("utf-8")
files['INSTALL_FIRST_TIME.bat'] = base64.b64decode('').decode("utf-8")
files['app/main.py'] = base64.b64decode('').decode("utf-8")
files['app/__init__.py'] = base64.b64decode('').decode("utf-8")
files['app/processors/__init__.py'] = base64.b64decode('').decode("utf-8")
files['app/processors/field_mapper.py'] = base64.b64decode('').decode("utf-8")
files['app/output/excel_writer.py'] = base64.b64decode('').decode("utf-8")
files['app/output/__init__.py'] = base64.b64decode('').decode("utf-8")
files['app/templates/index.html'] = base64.b64decode('').decode("utf-8")
files['app/extractors/image_extractor.py'] = base64.b64decode('').decode("utf-8")
files['app/extractors/text_extractor.py'] = base64.b64decode('').decode("utf-8")
files['app/extractors/pdf_extractor.py'] = base64.b64decode('').decode("utf-8")
files['app/extractors/excel_extractor.py'] = base64.b64decode('').decode("utf-8")
files['app/extractors/__init__.py'] = base64.b64decode('').decode("utf-8")
for path, content in files.items():
    os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
    open(path, 'w', encoding='utf-8').write(content)
print('Done! Now run: git add -A && git commit -m "Add bot" && git push origin claude/data-extraction-bot-Gpvpe')